package rstgo

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// The corpus under testdata/ holds reStructuredText inputs together with
// the output of the reference implementation (Docutils 0.23), generated by
// scripts/regen.sh.  The tests compare our output byte for byte.
//
// testdata/known_failures.txt lists the cases that are known to differ;
// they are reported but do not fail the test run.  Set RSTGO_UPDATE_KNOWN=1
// to rewrite that list from the current results.

type suiteFile struct {
	Origin   string         `json:"origin"`
	Settings map[string]any `json:"settings"`
	Cases    []struct {
		Name  string `json:"name"`
		Input string `json:"input"`
	} `json:"cases"`
}

type expectedFile struct {
	Cases []struct {
		Name  string  `json:"name"`
		Pxml  *string `json:"pxml"`
		HTML4 *string `json:"html4"`
		HTML5 *string `json:"html5"`
		Err   string  `json:"err"`
		Err4  *string `json:"err4"`
		Err5  *string `json:"err5"`
	} `json:"cases"`
}

type corpusStats struct {
	total, passed map[string]int
	failures      []string
}

func loadKnownFailures(t *testing.T) map[string]bool {
	known := map[string]bool{}
	data, err := os.ReadFile("testdata/known_failures.txt")
	if err != nil {
		return known
	}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		known[line] = true
	}
	return known
}

// optionsFromSettings maps Docutils setting names (as used in the fixture
// .json files and scripts/regen.py) to Options.
func optionsFromSettings(s map[string]any, o *Options) {
	b := func(k string) (bool, bool) { v, ok := s[k].(bool); return v, ok }
	if _, ok := s["default_stylesheet"]; !ok {
		o.NoStylesheet = true
	}
	for k, v := range s {
		switch k {
		case "default_stylesheet":
		case "stylesheet":
			o.NoStylesheet = false
			o.Stylesheet = strings.Split(v.(string), ",")
		case "embed_stylesheet":
			o.LinkStylesheet = !v.(bool)
		case "initial_header_level":
			o.InitialHeaderLevel = int(v.(float64))
		case "doctitle_xform":
			o.NoDocTitle = !v.(bool)
		case "docinfo_xform":
			o.NoDocInfo = !v.(bool)
		case "sectsubtitle_xform":
			o.SectionSubtitles = v.(bool)
		case "report_level":
			o.ReportLevel = int(v.(float64))
		case "halt_level":
			o.HaltLevel = int(v.(float64))
		case "file_insertion_enabled":
			o.NoFileInsertion = !v.(bool)
		case "raw_enabled":
			o.NoRaw = !v.(bool)
		case "tab_width":
			o.TabWidth = int(v.(float64))
		case "toc_backlinks":
			if v == nil {
				o.TocBacklinks = "none"
			} else {
				o.TocBacklinks = v.(string)
			}
		case "footnote_references":
			o.FootnoteReferences = v.(string)
		case "sectnum_xform":
			o.NoSectionNumbering = !v.(bool)
		case "strip_comments":
			o.StripComments = v.(bool)
		case "generator":
			o.Generator = v.(bool)
		case "source_link":
			o.SourceLink = v.(bool)
		case "source_url":
			o.SourceURL = v.(string)
		case "pep_references":
			o.PEPReferences = v.(bool)
		case "rfc_references":
			o.RFCReferences = v.(bool)
		case "trim_footnote_reference_space":
			x, _ := b(k)
			o.TrimFootnoteReferenceSpace = &x
		case "math_output":
			o.MathOutput = v.(string)
		case "cloak_email_addresses":
			o.CloakEmailAddresses = v.(bool)
		case "compact_lists":
			o.NoCompactLists = !v.(bool)
		case "compact_field_lists":
			o.NoCompactFieldLists = !v.(bool)
		case "table_style":
			o.TableStyle = v.(string)
		case "attribution":
			o.Attribution = v.(string)
		case "xml_declaration":
			o.XMLDeclaration, o.NoXMLDeclaration = v.(bool), !v.(bool)
		case "syntax_highlight":
			o.SyntaxHighlight = v.(string)
		case "character_level_inline_markup":
			o.CharacterLevelInlineMarkup = v.(bool)
		case "field_name_limit":
			o.FieldNameLimit = int(v.(float64))
			if o.FieldNameLimit == 0 {
				o.FieldNameLimit = -1
			}
		case "option_limit":
			o.OptionLimit = int(v.(float64))
			if o.OptionLimit == 0 {
				o.OptionLimit = -1
			}
		case "title":
			o.Title = v.(string)
		case "section_self_link":
			o.SectionSelfLink = v.(bool)
		case "line_length_limit":
			o.LineLengthLimit = int(v.(float64))
		case "footnote_backlinks":
			o.NoFootnoteBacklinks = !v.(bool)
		case "image_loading":
			o.ImageLoading = v.(string)
		case "strip_classes":
			for _, x := range v.([]any) {
				o.StripClasses = append(o.StripClasses, x.(string))
			}
		case "strip_elements_with_classes":
			for _, x := range v.([]any) {
				o.StripElementsWithClasses = append(o.StripElementsWithClasses, x.(string))
			}
		default:
			panic("unknown fixture setting " + k)
		}
	}
}

// runKind converts input with the given writer kind ("pxml", "html4",
// "html5"); halted reports a halt at a SEVERE system message.
func runKind(kind string, input []byte, opts Options) (out string, stderr string, halted bool, err error) {
	var errBuf bytes.Buffer
	opts.Stderr = &errBuf
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic: %v", r)
		}
	}()
	var res []byte
	switch kind {
	case "pxml":
		res, err = PseudoXML(input, opts)
	case "html4":
		opts.Writer = HTML4
		res, err = Convert(input, opts)
	case "html5":
		opts.Writer = HTML5
		res, err = Convert(input, opts)
	}
	if _, ok := err.(*haltError); ok {
		return "", errBuf.String(), true, nil
	}
	return string(res), errBuf.String(), false, err
}

var corpusKinds = []string{"pxml", "html4", "html5"}

func (st *corpusStats) check(t *testing.T, known map[string]bool, id, kind string, input []byte, opts Options, wantOut *string, wantErr string) {
	key := id + " " + kind
	st.total[kind]++
	out, stderr, halted, err := runKind(kind, input, opts)
	ok := err == nil
	if ok {
		if wantOut == nil {
			ok = halted
		} else {
			ok = !halted && out == *wantOut
		}
	}
	if ok && stderr != wantErr {
		ok = false
	}
	if ok {
		st.passed[kind]++
		if known[key] {
			t.Logf("%s: listed in known_failures.txt but passes", key)
		}
		return
	}
	st.failures = append(st.failures, key)
	if !known[key] {
		msg := "output differs"
		if err != nil {
			msg = err.Error()
		} else if wantOut != nil && !halted && out == *wantOut {
			msg = "stderr differs"
		}
		t.Errorf("%s: %s", key, msg)
	}
}

func TestCorpus(t *testing.T) {
	known := loadKnownFailures(t)
	st := &corpusStats{total: map[string]int{}, passed: map[string]int{}}

	// suites
	files, _ := filepath.Glob("testdata/suites/*.json")
	sort.Strings(files)
	for _, fn := range files {
		if strings.HasSuffix(fn, ".expected.json") {
			continue
		}
		var suite suiteFile
		var exp expectedFile
		data, err := os.ReadFile(fn)
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(data, &suite); err != nil {
			t.Fatalf("%s: %v", fn, err)
		}
		data, err = os.ReadFile(strings.TrimSuffix(fn, ".json") + ".expected.json")
		if err != nil {
			t.Fatalf("%s: missing expected output (run scripts/regen.sh): %v", fn, err)
		}
		if err := json.Unmarshal(data, &exp); err != nil {
			t.Fatalf("%s: %v", fn, err)
		}
		if len(exp.Cases) != len(suite.Cases) {
			t.Fatalf("%s: expected output out of date (run scripts/regen.sh)", fn)
		}
		name := strings.TrimSuffix(filepath.Base(fn), ".json")
		for i, c := range suite.Cases {
			e := exp.Cases[i]
			var opts Options
			settings := suite.Settings
			if settings == nil {
				settings = map[string]any{}
			}
			optionsFromSettings(settings, &opts)
			id := "suite:" + name + ":" + c.Name
			for _, kind := range corpusKinds {
				want, wantErr := e.Pxml, e.Err
				switch kind {
				case "html4":
					want = e.HTML4
					if e.Err4 != nil {
						wantErr = *e.Err4
					}
				case "html5":
					want = e.HTML5
					if e.Err5 != nil {
						wantErr = *e.Err5
					}
				}
				st.check(t, known, id, kind, []byte(c.Input), opts, want, wantErr)
			}
		}
	}

	// fixtures
	files, _ = filepath.Glob("testdata/fixtures/*.rst")
	sort.Strings(files)
	for _, fn := range files {
		base := strings.TrimSuffix(fn, ".rst")
		input, err := os.ReadFile(fn)
		if err != nil {
			t.Fatal(err)
		}
		settings := map[string]any{}
		if data, err := os.ReadFile(base + ".json"); err == nil {
			if err := json.Unmarshal(data, &settings); err != nil {
				t.Fatalf("%s.json: %v", base, err)
			}
		}
		for _, kind := range corpusKinds {
			opts := Options{SourcePath: fn}
			optionsFromSettings(settings, &opts)
			wantData, err := os.ReadFile(base + "." + kind)
			if err != nil {
				t.Fatalf("%s: missing expected output (run scripts/regen.sh)", fn)
			}
			wantErrData, _ := os.ReadFile(base + ".err")
			if kind != "pxml" {
				if d, err := os.ReadFile(base + ".err" + kind[len(kind)-1:]); err == nil {
					wantErrData = d
				}
			}
			want := string(wantData)
			wp := &want
			if want == "*** HALT ***\n" {
				wp = nil
			}
			st.check(t, known, "fixture:"+filepath.Base(base), kind, input, opts, wp, string(wantErrData))
		}
	}

	for _, kind := range corpusKinds {
		t.Logf("corpus %-5s: %d/%d cases identical to Docutils", kind, st.passed[kind], st.total[kind])
	}
	sort.Strings(st.failures)
	t.Logf("known failures listed: %d, failing now: %d", len(known), len(st.failures))
	if os.Getenv("RSTGO_UPDATE_KNOWN") != "" {
		var b strings.Builder
		b.WriteString("# Corpus cases whose output is known to differ from Docutils.\n")
		b.WriteString("# Format: <case id> <kind>.  Regenerate with RSTGO_UPDATE_KNOWN=1 go test -run TestCorpus\n")
		for _, f := range st.failures {
			b.WriteString(f + "\n")
		}
		if err := os.WriteFile("testdata/known_failures.txt", []byte(b.String()), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}
